    this.widget=widget;this.lang=(node.properties?.sqr_ui_lang||localStorage.getItem("sqr_ui_lang"))==="zh"?"zh":"en";this.imageInfoCache=new Map();this.colorPreviewCache=new Map();this.colorPreviewPending=new Set();
