const _wad2RenderLeftBase=Director.prototype.renderLeft;
Director.prototype.renderLeft=function(){
  _wad2RenderLeftBase.call(this);
  const s=this.state.segments[this.selected]; if(!s||!this.left)return;
  const refsBox=this.left.querySelector('.wad2-refs'), guide=this.left.querySelector('.wad2-guide')?.closest('.wad2-ref-wrap');
  if(guide){
    const card=guide.querySelector('.wad2-guide');
    if(card&&!card.querySelector('[data-guide-remove]')){
      const close=document.createElement('i');
      close.dataset.guideRemove='1';
      close.textContent='×';
      close.title=this.lang==='zh'?'删除比例引导帧':'Remove guide frame';
      close.onclick=e=>{e.stopPropagation();s.guide_frame=null;this.persist();this.render()};
      card.appendChild(close);
    }
    if((s.references||[]).length>=6&&refsBox){
      refsBox.style.flexWrap='wrap';
      refsBox.style.overflowX='hidden';
      guide.style.order='99';
      guide.style.flexBasis='100%';
      guide.style.width='var(--wad-ref-size,116px)';
      guide.style.minWidth='var(--wad-ref-size,116px)';
    }
  }
  this.left.querySelectorAll('.wad2-ref[data-r]').forEach(card=>{
    const index=Number(card.dataset.r), ref=s.references?.[index], person=this.refPerson(ref), label=card.querySelector('span');
    if(label&&!ref?.background&&person)label.textContent=`P${person}`;
  });
};

