window.LHImageEditorOpen=function(segment,{lang='zh',onChange=()=>{}}={}){
  const host={state:{segments:[segment]},selected:0,lang,standalone:true,imageInfoCache:new Map(),refPath:Director.prototype.refPath,t:key=>TEXT[lang]?.[key]||TEXT.en[key]||key,persist:()=>onChange(segment),render:()=>onChange(segment)};
  return Director.prototype.openComposeModal.call(host);
};

Director.prototype.uploadReferences=async function(files){
  const s=this.state.segments[this.selected];if(!s||!files?.length)return;
  const room=6-(s.references||[]).length;
  if(room<=0){alert(this.lang==='zh'?'当前分段最多只能使用 6 张参考图':'This segment can use up to 6 reference images');return}
  const fd=new FormData();[...files].slice(0,room).forEach(f=>fd.append("files[]",f));
  try{const response=await fetch("/sqr/upload_images",{method:"POST",body:fd}),data=await response.json();s.references=s.references||[];for(const path of data.saved||[])if(!s.references.some(r=>this.refPath(r)===path))s.references.push({path,background:false});this.persist();this.render()}catch(error){alert(`参考图上传失败: ${error}`)}
};

Director.prototype.cloneRefEntry=function(ref){return typeof ref==='string'?{path:ref,background:false}:{...(ref||{})}};
Director.prototype.checkDirectorResume=async function(){
  const button=this.topTools?.querySelector('[data-a="resume"]');
  if(button)button.disabled=true;
  try{
    const response=await fetch(`/sqr/director_checkpoint?uid=${encodeURIComponent(String(this.node.id))}`),data=await response.json(),ckpt=data.checkpoint;
    if(!ckpt){alert(this.lang==='zh'?'没有找到这个导演台节点未完成的任务记录。':'No unfinished run was found for this Director node.');return}
    const next=Math.max(1,Number(ckpt.next_seg)||1),total=Math.max(next,Number(ckpt.total_segs)||next),missing=Array.isArray(ckpt.missing)?ckpt.missing:[];
    const summary=this.lang==='zh'
      ?`找到未完成任务：已完成第 ${ckpt.completed_seg||0}/${total} 段，将从第 ${next} 段继续。${missing.length?`\n\n缺失部分素材和设定，请手动补全：\n- ${missing.join('\n- ')}`:''}\n\n是否加载这份记录？`
      :`Interrupted run found: ${ckpt.completed_seg||0}/${total} segment(s) completed. Resume from segment ${next}.${missing.length?`\n\nSome assets or settings are missing; please complete them manually:\n- ${missing.join('\n- ')}`:''}\n\nLoad this record?`;
    if(!confirm(summary))return;

    const snapshot=ckpt.director_snapshot;
    if(snapshot&&Array.isArray(snapshot.segments)&&snapshot.segments.length){
      this.state=JSON.parse(JSON.stringify(snapshot));
      this.state.version=Math.max(3,Number(this.state.version)||3);
      this.state.nextColorIndex??=this.state.segments.length;
      this.state.segments.forEach((segment,index)=>{segment.color||=segmentColor(index);segment.references=Array.isArray(segment.references)?segment.references:[]});
      this.selected=clamp(next-1,0,this.state.segments.length-1);
    }
    const settings=ckpt.director_settings||{};
    setVal(this.node,K.transition,Boolean(settings.transition_enabled));
    setVal(this.node,K.multi,Boolean(settings.multi_ref_enabled));
    setVal(this.node,K.replace,Boolean(settings.replacement_enabled));
    if(settings.video_node_id)setVal(this.node,K.videoId,String(settings.video_node_id));
    if(settings.reference_node_id)setVal(this.node,K.refId,String(settings.reference_node_id));
    if(settings.motion_node_id)setVal(this.node,K.motionId,String(settings.motion_node_id));
    if(settings.output_node_id)setVal(this.node,K.outputId,String(settings.output_node_id));
    setVal(this.node,K.start,next);
    setVal(this.node,K.resumePath,String(ckpt.transition_video||''));
    setVal(this.node,K.resume,Boolean(ckpt.transition_video));
    setVal(this.node,'sqr_pre_segments',(ckpt.segment_outputs||[]).join(','));
    setVal(this.node,'sqr_frame_offset',Number.isFinite(Number(ckpt.base_frame_offset))?Number(ckpt.base_frame_offset):-1);

    const params=ckpt.ref_video_params||{},videoNode=app.graph?.getNodeById?.(Number(settings.video_node_id||val(this.node,K.videoId,'')));
    if(videoNode&&params){for(const name of ['video','force_rate','frame_load_cap','skip_first_frames','select_every_nth']){if(params[name]===undefined)continue;const widget=videoNode.widgets?.find(w=>w.name===name);if(widget){widget.value=params[name];widget.callback?.(params[name])}}videoNode.setDirtyCanvas?.(true,true)}
    this.syncMultiRef(Boolean(settings.multi_ref_enabled));this.syncReplacement(Boolean(settings.replacement_enabled));this.persist();this.refreshSource(true);this.render();
    alert(this.lang==='zh'
      ?`续跑记录已加载，将从第 ${next} 段开始。${missing.length?'\n缺失部分素材和设定，请手动补全。':''}`
      :`Recovery loaded. Execution will start from segment ${next}.${missing.length?'\nSome assets or settings are missing; please complete them manually.':''}`);
  }catch(error){alert(`${this.lang==='zh'?'读取续跑记录失败':'Failed to read recovery record'}: ${error}`)}finally{if(button)button.disabled=false}
};
Director.prototype.cloneCharacterLock=function(lock){return lock&&typeof lock==='object'?JSON.parse(JSON.stringify(lock)):{enabled:true,no_swap:true,descriptions:{}}};
Director.prototype.cloneSegmentForNewRange=function(segment,overrides={}){
  return {...segment,...overrides,character_lock:this.cloneCharacterLock(segment?.character_lock),references:(segment?.references||[]).map(r=>this.cloneRefEntry(r))};
};
Director.prototype.composePositivePreview=function(segment,index=this.selected){
  let base='';for(let i=0;i<=index;i++){const value=String(this.state.segments[i]?.positive||'').trim();if(value)base=value}
  const people=this.segmentPeople(segment),lock=segment?.character_lock||{},desc=lock.descriptions||{},lines=[];
  if(lock.enabled!==false)for(const p of people){const text=String(desc[String(p)]||'').trim();if(text)lines.push(`P${p}: ${text}`)}
  if(!lines.length)return base;
  const suffix=[`Character lock:`,...lines,`Preserve each P character's face, hairstyle, outfit, color palette, and identity from that character's own reference images.`];
  if(lock.no_swap!==false&&lines.length>1)suffix.push(`Do not swap clothes, hair, face, colors, or identity between P characters.`);
  return `${base}${base?'\n\n':''}${suffix.join(' ')}`;
};

Director.prototype.applyEqualSegmentsDynamic=function(value){
  const minimum=this.minSegmentFrames(),count=clamp(Math.round(Number(value)||1),1,100),maxCount=Math.max(1,Math.min(100,Math.floor(this.total/minimum)));
  if(count>maxCount){alert(this.lang==='zh'?`无法平均分为 ${count} 段：当前最小分段为 ${minimum} 帧，最多 ${maxCount} 段。`:`Cannot create ${count} segments: minimum ${minimum} frame(s), maximum ${maxCount} segments.`);return}
  const previous=this.state.segments,template=previous[this.selected]||previous[0]||{mode:"transfer",multi_ref:false};
  this.state.segments=Array.from({length:count},(_,i)=>{const old=previous[i],start=Math.round(this.total*i/count),end=Math.round(this.total*(i+1)/count),source=old||template;return this.cloneSegmentForNewRange(source,{id:old?.id||`seg_${Date.now()}_${i}`,start,end,enabled:true,positive:old?.positive||"",mode:template.mode||"transfer",multi_ref:Boolean(template.multi_ref),guide_frame:old?.guide_frame||null,sam3_marking:old?.sam3_marking?JSON.parse(JSON.stringify(old.sam3_marking)):null,color_match:Boolean(old?.color_match),color_match_strength:clamp(Number(old?.color_match_strength??1),0,10),references:old?(old.references||[]).map(r=>this.cloneRefEntry(r)):[],color:old?.color||segmentColor(this.state.nextColorIndex++)})});
  this.selected=Math.min(this.selected,count-1);this.syncMultiRef(Boolean(template.multi_ref));this.syncReplacement(template.mode==="replacement");this.persist();this.render();
};

Director.prototype.splitAtPlayhead=function(){
  const idx=this.state.segments.findIndex(x=>this.playhead>x.start&&this.playhead<x.end),segment=this.state.segments[idx];if(!segment)return;
  const minimum=this.minSegmentFrames(),left=this.playhead-segment.start,right=segment.end-this.playhead;
  if(left<minimum||right<minimum){alert(this.lang==='zh'?`无法切片：当前最小分段为 ${minimum} 帧。左右为 ${left} / ${right} 帧。`:`Cannot cut: minimum is ${minimum} frame(s). Left/right: ${left} / ${right}.`);return}
  const next=this.cloneSegmentForNewRange(segment,{id:`seg_${Date.now()}`,start:this.playhead,positive:"",guide_frame:null,sam3_marking:null,references:[],color:segmentColor(this.state.nextColorIndex++)});
  segment.end=this.playhead;this.state.segments.splice(idx+1,0,next);this.selected=idx+1;this.persist();this.render();
};

const _wad2DetectSceneCutsBase=Director.prototype.detectSceneCuts;
Director.prototype.detectSceneCuts=async function(){
  const before=this.state.segments.map(s=>s.id).join('|'),source=this.state.segments[this.selected];
  await _wad2DetectSceneCutsBase.call(this);
  if(before===this.state.segments.map(s=>s.id).join('|'))return;
  const lock=this.cloneCharacterLock(source?.character_lock);
  for(const seg of this.state.segments)if(seg.id&&String(seg.id).startsWith('seg_cut_')&&!seg.character_lock)seg.character_lock=this.cloneCharacterLock(lock);
  this.persist();this.render();
};

const _wad2OpenSam3TagModalBase=Director.prototype.openSam3TagModal;
Director.prototype.openSam3TagModal=function(){
  const segment=this.state.segments[this.selected];
  if(this.segmentPeople(segment).length>1){alert(this.lang==='zh'?'多人多参模式暂不使用单人 SAM3 打标；请使用 Video Mask 区域的 SAM 提示词自动识别多人。':'Multi-person mode does not use single-subject SAM3 tagging yet. Use the Video Mask SAM prompt for automatic multi-person detection.');return}
  return _wad2OpenSam3TagModalBase.call(this);
};

const _wad2RenderPromptBase=Director.prototype.renderPrompt;
Director.prototype.renderPrompt=function(){
  _wad2RenderPromptBase.call(this);
  const segment=this.state.segments[this.selected];if(!segment||!this.promptWrap)return;
  let preview=this.promptWrap.querySelector('.wad2-positive-preview');
  if(!preview){preview=document.createElement('details');preview.className='wad2-positive-preview';preview.style.cssText='margin-top:6px;color:#aaa;font-size:10px';preview.innerHTML=`<summary>${this.lang==='zh'?'合成后 Positive 预览':'Composed Positive Preview'}</summary><pre style="white-space:pre-wrap;background:#101010;border:1px solid #333;border-radius:5px;padding:6px;max-height:120px;overflow:auto"></pre>`;this.promptWrap.appendChild(preview)}
  preview.querySelector('pre').textContent=this.composePositivePreview(segment,this.selected);
};

